<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';

use Prometheus\admin\AdminGuard;
use Prometheus\core\Database;

AdminGuard::requireAdmin();
if (session_status() === PHP_SESSION_NONE) session_start();
$symbol=prometheus_config('default_symbol','BTCUSDT');
$mode=($_GET['mode']??'DIRECTIONAL')==='STRATEGY'?'STRATEGY':'DIRECTIONAL';
$csrf=(string)($_SESSION['paper_trading_csrf']??'');
if($csrf===''){ $csrf=bin2hex(random_bytes(32)); $_SESSION['paper_trading_csrf']=$csrf; }
$notice=null;$error=null;$config=null;$account=null;$heartbeat=null;$priceRow=null;$predictions=[];$decisions=[];$trades=[];$curve=[];$moduleSignals=[];$stats=[];$athenaStats=[];$researchModes=[];$ready=true;

if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&isset($_POST['save_config'])){
    if(!isset($_POST['csrf'])||!hash_equals($csrf,(string)$_POST['csrf']))$error='A sessão expirou. Atualize a página e tente novamente.';
    else {
        $allocation=(float)($_POST['allocation_pct']??0);$fee=(float)($_POST['fee_pct']??0);$slippage=(float)($_POST['slippage_pct']??0);
        $minEdge=(float)($_POST['min_edge_pct']??0);$minConfidence=(float)($_POST['min_confidence']??0);
        $cooldown=(int)($_POST['cooldown_minutes']??0);$stop=(float)($_POST['stop_loss_pct']??0);$take=(float)($_POST['take_profit_pct']??0);
        $maxMinutes=(int)($_POST['max_position_minutes']??0);$initial=(float)($_POST['initial_balance']??100);
        if($allocation<=0||$allocation>50||$fee<0||$fee>5||$slippage<0||$slippage>5||$minEdge<0||$minConfidence<0||$minConfidence>1||$cooldown<0||$stop<0||$take<0||$maxMinutes<1||$initial<1)$error='Revise os limites: alocação 0–50%, custos até 5%, confiança 0–1 e saldo inicial positivo.';
        else {
            try{
                $existing=Database::fetch('SELECT position_side FROM paper_trading_v2_accounts WHERE mode=?',[$mode]);
                if($existing&&$existing['position_side']!=='FLAT'&&isset($_POST['initial_balance']))$error='O saldo inicial só pode ser alterado com a posição zerada.';
                else{
                    Database::execute('UPDATE paper_trading_config SET enabled=?,initial_balance=?,allocation_pct=?,allow_short=?,fee_pct=?,slippage_pct=?,min_edge_pct=?,min_confidence=?,cooldown_minutes=?,reversal_policy=?,stop_loss_pct=?,take_profit_pct=?,max_position_minutes=? WHERE mode=?',[
                        isset($_POST['enabled'])?1:0,$initial,$allocation,isset($_POST['allow_short'])?1:0,$fee,$slippage,$minEdge,$minConfidence,$cooldown,
                        ($_POST['reversal_policy']??'CLOSE_REVERSE')==='CLOSE_ONLY'?'CLOSE_ONLY':'CLOSE_REVERSE',$stop,$take,$maxMinutes,$mode]);
                    $tradesExist=(int)(Database::fetch('SELECT COUNT(*) n FROM paper_trading_v2_trades WHERE mode=?',[$mode])['n']??0);
                    if(!$existing||($existing['position_side']==='FLAT'&&$tradesExist===0))Database::execute('UPDATE paper_trading_v2_accounts SET initial_balance=?,cash_balance=?,peak_equity=? WHERE mode=? AND position_side="FLAT"',[$initial,$initial,$initial,$mode]);
                    $notice='Configurações salvas para o modo '.$mode.'.';
                }
            }catch(Throwable $e){$error='Não foi possível salvar. Confirme se a migration 011 foi aplicada.';}
        }
    }
    $_SESSION['paper_trading_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['paper_trading_csrf'];
}

try{
    $config=Database::fetch('SELECT * FROM paper_trading_config WHERE mode=?',[$mode]);
    $account=Database::fetch('SELECT * FROM paper_trading_v2_accounts WHERE mode=?',[$mode]);
    $heartbeat=Database::fetch('SELECT * FROM paper_trading_heartbeat WHERE mode=?',[$mode]);
    $priceRow=Database::fetch('SELECT id,close_price,open_time,close_time,available_at,ingested_at FROM market_data WHERE symbol=? AND interval_name=? AND close_time<=NOW() AND ingested_at IS NOT NULL AND ingested_at<=UTC_TIMESTAMP() AND temporal_quality IN ("EXACT","INGESTION_ONLY") AND (available_at IS NULL OR (available_at<=UTC_TIMESTAMP() AND ingested_at>=available_at)) ORDER BY close_time DESC LIMIT 1',[$symbol,prometheus_config('collector.market_interval','1m')]);
    if(!$config||!$account||!$heartbeat){$ready=false;} else {
        $decisions=Database::fetchAll('SELECT * FROM paper_trading_decisions WHERE mode=? ORDER BY id DESC LIMIT 40',[$mode]);
        $trades=Database::fetchAll('SELECT * FROM paper_trading_v2_trades WHERE mode=? ORDER BY exit_at DESC,id DESC LIMIT 30',[$mode]);
        $curve=Database::fetchAll('SELECT id,prediction_id,price_timestamp,reference_price,equity FROM paper_trading_equity WHERE mode=? ORDER BY created_at DESC,id DESC LIMIT 720',[$mode]);$curve=array_reverse($curve);
        foreach(['15m','1h','4h','24h'] as $h){$r=Database::fetch('SELECT * FROM predictions WHERE symbol=? AND horizon=? AND created_at<=NOW() ORDER BY id DESC LIMIT 1',[$symbol,$h]);if($r)$predictions[$h]=$r;}
        $latest15=$predictions['15m']??null;
        if($latest15){
            $signalData=json_decode((string)$latest15['signals_json'],true)?:[];$weights=json_decode((string)$latest15['weights_json'],true)?:[];
            $present=[];$denominator=0.0;
            foreach($signalData as $s){if(($s['status']??'AVAILABLE')==='AVAILABLE'||($s['status']??'')==='STALE'){$w=(float)($weights[$s['module']]??1);$eff=$w*max(.05,(float)$s['confidence']);$denominator+=$eff;$present[$s['module']]=['signal'=>(float)$s['value'],'confidence'=>(float)$s['confidence'],'weight'=>$w,'effective'=>$eff,'contribution'=>(float)$s['value']*$eff,'status'=>(string)($s['status']??'AVAILABLE')];}}
            foreach($present as &$s)$s['contribution_share']=$denominator>0?$s['effective']/$denominator*100:0;unset($s);$moduleSignals=$present;
        }
        $stats=Database::fetch('SELECT COUNT(*) n,SUM(net_pnl>0) wins,SUM(net_pnl<0) losses,SUM(GREATEST(net_pnl,0)) gains,SUM(ABS(LEAST(net_pnl,0))) loss_sum,SUM(fees_usd) fees,SUM(slippage_usd) slippage,AVG(net_pnl) expectancy FROM paper_trading_v2_trades WHERE mode=?',[$mode])??[];
        foreach(['DIRECTIONAL','STRATEGY'] as $researchMode){$researchAccount=Database::fetch('SELECT * FROM paper_trading_v2_accounts WHERE mode=?',[$researchMode]);$researchStats=Database::fetch('SELECT COUNT(*) n,SUM(net_pnl>0) wins,SUM(GREATEST(net_pnl,0)) gains,SUM(ABS(LEAST(net_pnl,0))) loss_sum,SUM(fees_usd+slippage_usd) costs FROM paper_trading_v2_trades WHERE mode=?',[$researchMode]);$researchModes[$researchMode]=['account'=>$researchAccount,'stats'=>$researchStats];}
        try{$athenaStats=Database::fetchAll('SELECT s.horizon,s.regime,COUNT(*) n,AVG(p.probability_up) classic_mean_p,AVG(s.shadow_probability_up) shadow_mean_p,AVG(s.classic_hit) classic_accuracy,AVG(s.shadow_hit) shadow_accuracy,AVG(s.classic_brier) classic_brier,AVG(s.shadow_brier) shadow_brier,AVG(CASE WHEN s.actual_direction="UP" THEN -LN(GREATEST(0.000000001,s.shadow_probability_up)) WHEN s.actual_direction="DOWN" THEN -LN(GREATEST(0.000000001,1-s.shadow_probability_up)) ELSE NULL END) shadow_logloss,AVG(CASE WHEN s.actual_direction="UP" THEN -LN(GREATEST(0.000000001,p.probability_up)) WHEN s.actual_direction="DOWN" THEN -LN(GREATEST(0.000000001,1-p.probability_up)) ELSE NULL END) classic_logloss FROM athena50_shadow_predictions s JOIN predictions p ON p.id=s.prediction_id WHERE s.model_status IN ("READY","READY_PARTIAL") AND s.actual_direction IN ("UP","DOWN") GROUP BY s.horizon,s.regime ORDER BY FIELD(s.horizon,"15m","1h","4h","24h"),s.regime');}catch(Throwable $ignored){$athenaStats=[];}
    }
}catch(Throwable $e){$ready=false;}

$price=(float)($priceRow['close_price']??0);$cash=(float)($account['cash_balance']??100);$qty=(float)($account['quantity_btc']??0);$side=(string)($account['position_side']??'FLAT');
$unrealized=$side==='FLAT'?0:($price-(float)$account['entry_price'])*$qty*($side==='LONG'?1:-1);
$equity=\Prometheus\core\PaperTrader::markedEquity($account??[],$price);
$initial=(float)($account['initial_balance']??100);$realized=(float)($account['realized_pnl']??0);$totalPnl=$equity-$initial;$returnPct=$initial>0?$totalPnl/$initial*100:0;
$nTrades=(int)($stats['n']??0);$wins=(int)($stats['wins']??0);$lossSum=(float)($stats['loss_sum']??0);$profitFactor=$lossSum>0?(float)($stats['gains']??0)/$lossSum:null;$winRate=$nTrades>0?$wins/$nTrades*100:null;
$heartbeatAge=$heartbeat&&$heartbeat['last_finished_at']?time()-strtotime((string)$heartbeat['last_finished_at']):PHP_INT_MAX;
$heartbeatStatus=!$ready?'MIGRATION PENDENTE':((int)($config['enabled']??0)===0?'PARADO':(($heartbeat['status']??'STOPPED')==='ERROR'?'ERRO':($heartbeatAge>300?'ATRASADO':'ATIVO')));
$decisionLabels=['OPEN_LONG'=>'ABRIR LONG','OPEN_SHORT'=>'ABRIR SHORT','CLOSE_LONG'=>'FECHAR LONG','CLOSE_SHORT'=>'FECHAR SHORT','HOLD_LONG'=>'MANTER LONG','HOLD_SHORT'=>'MANTER SHORT','NO_TRADE'=>'NÃO OPERAR','INDETERMINATE'=>'INDETERMINADA'];
$labels=['UP'=>'ALTA','DOWN'=>'BAIXA','INDETERMINATE'=>'INDEFINIDA'];
$series=[];$buyHold=[];$startPrice=(float)($curve[0]['reference_price']??0);
foreach($curve as $point){$series[]=['x'=>strtotime((string)$point['price_timestamp'])*1000,'y'=>(float)$point['equity']];$buyHold[]=['x'=>strtotime((string)$point['price_timestamp'])*1000,'y'=>$startPrice>0?$initial*(float)$point['reference_price']/$startPrice:$initial];}
function ptMoney(float $n):string{return '$'.number_format($n,2,',','.');}
function ptPct(float $n):string{return ($n>0?'+':'').number_format($n,2,',','.').'%';}
?>
