<section class="row g-3 mb-3">
<?php $cards=[['Capital inicial',ptMoney($initial)],['Equity atual',ptMoney($equity)],['Cash',ptMoney($cash)],['Exposição',ptMoney($qty*$price)],['Posição simulada',$side==='FLAT'?'FLAT':($side==='SHORT'?'SHORT simulado':'LONG')],['Entrada média',$side==='FLAT'?'—':ptMoney((float)$account['entry_price'])],['PnL aberto',ptMoney($unrealized)],['PnL realizado',ptMoney($realized)],['PnL total / retorno',ptMoney($totalPnl).' · '.ptPct($returnPct)],['Max drawdown',ptPct((float)($account['max_drawdown_pct']??0))],['Trades · acerto',$nTrades.' · '.($winRate===null?'—':number_format($winRate,1,',','.').'%')],['Profit factor',$profitFactor===null?'—':number_format($profitFactor,2,',','.').' · custos '.ptMoney((float)($account['total_fees']??0)+(float)($account['total_slippage']??0))]];foreach($cards as $c):?><div class="col-6 col-md-4 col-xl-2"><div class="metric h-100"><span><?=htmlspecialchars($c[0])?></span><strong class="fs-5"><?=htmlspecialchars($c[1])?></strong></div></div><?php endforeach;?>
</section>
<section class="row g-3 mb-3"><div class="col-12 col-xl-7"><div class="panel h-100"><h2>Decisão do PROMETHEUS</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Período</th><th>Direção</th><th>P(alta)</th><th>P(baixa)</th><th>Edge</th><th>Confiança</th></tr></thead><tbody><?php foreach(['15m','1h','4h','24h'] as $h):$p=$predictions[$h]??null;?><tr><td><?=$h?></td><?php if($p):?><td class="<?=$p['predicted_direction']==='UP'?'signal-up':($p['predicted_direction']==='DOWN'?'signal-down':'')?>"><?=$labels[$p['predicted_direction']]??$p['predicted_direction']?></td><td><?=number_format((float)$p['probability_up']*100,1,',','.')?>%</td><td><?=number_format((float)$p['probability_down']*100,1,',','.')?>%</td><td><?=number_format((float)$p['edge']*100,2,',','.')?> p.p.</td><td><?=number_format((float)$p['confidence']*100,1,',','.')?>%</td><?php else:?><td colspan="5" class="text-muted">Aguardando previsão</td><?php endif;?></tr><?php endforeach;?></tbody></table></div><p class="mb-0">Condição de mercado: <strong><?=htmlspecialchars((string)($predictions['15m']['regime']??'indisponível'))?></strong></p></div></div>
