<section class="row g-3 mb-3"><div class="col-12 col-xl-7"><div class="panel"><h2>Diagnóstico do ensemble usado na previsão de 15m</h2><?php if(!$moduleSignals):?><p class="text-muted">Sem snapshot disponível.</p><?php else:?><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Módulo</th><th>Sinal</th><th>Conf.</th><th>Peso</th><th>Peso efetivo</th><th>Contribuição</th><th>Status</th></tr></thead><tbody><?php foreach($moduleSignals as $name=>$s):?><tr><td><?=htmlspecialchars($name)?></td><td><?=number_format($s['signal'],3,',','.')?></td><td><?=number_format($s['confidence']*100,1,',','.')?>%</td><td><?=number_format($s['weight'],3,',','.')?></td><td><?=number_format($s['effective'],3,',','.')?></td><td><?=number_format($s['contribution'],4,',','.')?> · <?=number_format($s['contribution_share'],1,',','.')?>%</td><td><?=htmlspecialchars($s['status'])?></td></tr><?php endforeach;?></tbody></table></div><small class="text-muted">Sinal bruto do ensemble: <?=number_format((float)($predictions['15m']['ensemble_signal']??0),4,',','.')?> · probabilidade calculada separadamente da decisão de trading.</small><?php endif;?></div></div>
