<?php foreach($researchModes as $researchMode=>$rm):$ra=$rm['account']??[];$rs=$rm['stats']??[];$rn=(int)($rs['n']??0);$rwr=$rn>0?(float)($rs['wins']??0)/$rn*100:null;$rloss=(float)($rs['loss_sum']??0);$rpf=$rloss>0?(float)($rs['gains']??0)/$rloss:null;$rside=(string)($ra['position_side']??'FLAT');$rqty=(float)($ra['quantity_btc']??0);$rentry=(float)($ra['entry_price']??0);$rreserve=(float)($ra['reserved_cash']??0);$re=(float)($ra['cash_balance']??0)+($rside==='LONG'?$rqty*$price:($rside==='SHORT'?$rreserve+($price-$rentry)*$rqty*-1:$rreserve));?>
<tr><td>PROMETHEUS · <?=htmlspecialchars($researchMode)?></td><td>desde o início</td><td><?=$rn?></td><td><?=ptMoney($re-(float)($ra['initial_balance']??100))?> · <?=$rwr===null?'—':number_format($rwr,1,',','.').'%'?></td><td><?=ptPct((float)($ra['max_drawdown_pct']??0))?></td><td><?=$rpf===null?'—':number_format($rpf,2,',','.')?></td><td><?=ptMoney((float)($rs['costs']??0))?></td></tr><?php endforeach;?>
<?php foreach($athenaStats as $s):?><tr><td>ATHENA_CLASSIC × ATHENA-50 shadow</td><td><?=htmlspecialchars((string)$s['horizon'].' · '.$s['regime'])?></td><td><?=(int)$s['n']?></td><td><?=number_format((float)$s['classic_accuracy']*100,1,',','.')?>% × <?=number_format((float)$s['shadow_accuracy']*100,1,',','.')?>%</td><td><?=number_format((float)$s['classic_brier'],4,',','.')?> × <?=number_format((float)$s['shadow_brier'],4,',','.')?></td><td><?=number_format((float)$s['classic_logloss'],4,',','.')?> × <?=number_format((float)$s['shadow_logloss'],4,',','.')?></td><td>—</td></tr><?php endforeach;?>
<?php if(!$athenaStats):?><tr><td>ATHENA_CLASSIC × ATHENA-50 shadow</td><td>mesmas previsões avaliadas</td><td colspan="5" class="text-muted">Sem amostra avaliada ainda, ou migration 012 pendente.</td></tr><?php endif;?></tbody></table></div>
<small class="text-muted">A tabela não declara estratégia lucrativa. Leia as métricas junto do N; o shadow não participa do ensemble.</small></section>
<section class="panel mb-3"><h2>Configurações persistentes · <?=htmlspecialchars($mode)?></h2><form method="post" class="row g-2 align-items-end"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="save_config" value="1"><div class="col-auto form-check ms-2"><input class="form-check-input" type="checkbox" name="enabled" id="enabled" <?=!empty($config['enabled'])?'checked':''?>><label class="form-check-label" for="enabled">Ativo</label></div><div class="col-auto form-check ms-2"><input class="form-check-input" type="checkbox" name="allow_short" id="allowShort" <?=!empty($config['allow_short'])?'checked':''?>><label class="form-check-label" for="allowShort">Permitir SHORT sintético</label></div><?php $fields=[['initial_balance','Saldo inicial',100,.01],['allocation_pct','Alocação %',25,.1],['fee_pct','Taxa % por lado',.1,.001],['slippage_pct','Slippage % por lado',.02,.001],['min_edge_pct','Margem mínima %',.03,.001],['min_confidence','Confiança mínima (0–1)',.2,.01],['cooldown_minutes','Intervalo (min)',15,1],['stop_loss_pct','Stop %',.35,.01],['take_profit_pct','Alvo %',.7,.01],['max_position_minutes','Tempo máximo (min)',60,1]];foreach($fields as [$key,$label,$fallback,$step]):?><div class="col-6 col-md-3 col-xl-2"><label class="form-label small" for="<?=htmlspecialchars($key)?>"><?=htmlspecialchars($label)?></label><input class="form-control form-control-sm" id="<?=htmlspecialchars($key)?>" name="<?=htmlspecialchars($key)?>" type="number" step="<?=$step?>" value="<?=htmlspecialchars((string)($config[$key]??$fallback))?>"></div><?php endforeach;?><div class="col-6 col-md-3 col-xl-2"><label class="form-label small" for="reversal_policy">Reversão</label><select class="form-select form-select-sm" name="reversal_policy" id="reversal_policy"><option value="CLOSE_REVERSE" <?=($config['reversal_policy']??'')==='CLOSE_REVERSE'?'selected':''?>>Fecha e inverte</option><option value="CLOSE_ONLY" <?=($config['reversal_policy']??'')==='CLOSE_ONLY'?'selected':''?>>Só fecha</option></select></div><div class="col-auto"><button class="btn btn-primary btn-sm" type="submit">Salvar configuração</button></div></form><small class="text-muted d-block mt-2">Cada modo usa uma conta paper independente. DIRECTIONAL acompanha a direção; STRATEGY pode registrar NÃO OPERAR. Alocação máxima permitida: 50%, sem alavancagem.</small></section>
<section class="panel mb-3"><h2>Registro de decisões · inclusive sem operação</h2><div class="table-responsive"><table class="table table-sm sim-table align-middle"><thead><tr><th>Data e hora</th><th>ID previsão</th><th>Horizonte</th><th>Direção</th><th>P alta</th><th>P baixa</th><th>Edge</th><th>Conf.</th><th>Regime</th><th>Decisão</th><th>Motivo</th></tr></thead><tbody><?php foreach($decisions as $d):?><tr><td><?=htmlspecialchars((string)$d['created_at'])?></td><td>#<?=(int)$d['prediction_id']?></td><td><?=htmlspecialchars((string)$d['horizon'])?></td><td><?=htmlspecialchars($labels[$d['predicted_direction']]??$d['predicted_direction'])?></td><td><?=number_format((float)$d['probability_up']*100,1,',','.')?>%</td><td><?=number_format((float)$d['probability_down']*100,1,',','.')?>%</td><td><?=number_format((float)$d['edge']*100,2,',','.')?></td><td><?=number_format((float)$d['confidence']*100,1,',','.')?>%</td><td><?=htmlspecialchars((string)$d['regime'])?></td><td><?=htmlspecialchars($decisionLabels[$d['decision']]??$d['decision'])?></td><td title="<?=htmlspecialchars((string)$d['reason'],ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars(mb_strimwidth((string)$d['reason'],0,70,'…','UTF-8'))?></td></tr><?php endforeach;?><?php if(!$decisions):?><tr><td colspan="11" class="text-muted">Ainda não há previsões processadas pelo modo <?=htmlspecialchars($mode)?>. O heartbeat acima indica se o cron está chegando ao simulador.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><h2>Operações encerradas</h2><div class="table-responsive"><table class="table table-sm sim-table"><thead><tr><th>Entrada</th><th>Saída</th><th>Posição</th><th>Preço entrada</th><th>Preço saída</th><th>Quantidade</th><th>Duração</th><th>PnL bruto</th><th>Taxas</th><th>Slippage</th><th>PnL líquido</th><th>Motivo entrada / saída</th></tr></thead><tbody><?php foreach($trades as $t):?><tr><td><?=htmlspecialchars((string)$t['entry_at'])?></td><td><?=htmlspecialchars((string)$t['exit_at'])?></td><td><?=$t['side']==='SHORT'?'SHORT simulado':'LONG'?></td><td><?=ptMoney((float)$t['entry_price'])?></td><td><?=ptMoney((float)$t['exit_price'])?></td><td><?=number_format((float)$t['quantity_btc'],8,',','.')?> BTC</td><td><?=floor((int)$t['hold_seconds']/60)?> min</td><td><?=ptMoney((float)$t['gross_pnl'])?></td><td><?=ptMoney((float)$t['fees_usd'])?></td><td><?=ptMoney((float)$t['slippage_usd'])?></td><td><?=ptMoney((float)$t['net_pnl'])?></td><td title="<?=htmlspecialchars((string)$t['entry_reason'].' / '.(string)$t['exit_reason'],ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars(mb_strimwidth((string)$t['entry_reason'].' / '.(string)$t['exit_reason'],0,55,'…','UTF-8'))?></td></tr><?php endforeach;?><?php if(!$trades):?><tr><td colspan="12" class="text-muted">Nenhuma posição encerrada neste modo.</td></tr><?php endif;?></tbody></table></div></section>
